      throw new Error("A configured question appears twice in this Typeform response");
    if (!found.length) return [column, null];
    const answer = found[0];
    let value;
    if (answer.type === "choice") value = answer.choice?.label;
    else if (
      answer.type === "choices" &&
      Array.isArray(answer.choices?.labels) &&
      answer.choices.labels.every((label) => typeof label === "string")
