      !(
        typeof value === "string" &&
        value.length <= 4096 &&
        !/[\x00-\x1f\x7f]/.test(value.replace(/[\r\n\t]/g, ""))
      ) &&
      !(typeof value === "number" && Number.isFinite(value)) &&
      typeof value !== "boolean"
